__def("src/core/text.js", function () {
// Invisible characters a model may leak (zero-width space, word joiner, byte-order mark, soft hyphen). The zero-width
// joiner is kept: emoji sequences need it.
const INVISIBLE = /[\u200B\u2060\uFEFF\u00AD]/g;
/** Never ends in half of an emoji (a lone surrogate) after a cut. */
const dropHalfChar = (s) => s.replace(/[\uD800-\uDBFF]$/, '');

function capitalizeFirst(s) {
  const str = String(s ?? '');
  return str ? str.charAt(0).toUpperCase() + str.slice(1) : str;
}

/** Drops invisible characters, collapses whitespace, trims and caps the length (never half an emoji). */
function cleanString(s, max = 200) {
  return dropHalfChar(String(s ?? '').replace(INVISIBLE, '').replace(/\s+/g, ' ').trim().slice(0, max));
}

/** One line, at most `max` characters, marked with "…" when cut. */
function oneLine(text, max = 500) {
  const s = String(text ?? '').replace(INVISIBLE, '').replace(/\s+/g, ' ').trim();
  if (s.length <= max) return s;
  return `${dropHalfChar(s.slice(0, max - 1))}…`;
}

/** "in the kitchen" -> "In the kitchen." No period after one already there, or after the "…" of a cut. */
function toSentence(s) {
  const str = String(s ?? '');
  return capitalizeFirst(/[.!?…]$/.test(str) ? str : `${str}.`);
}

/** Cuts at a word boundary and marks the cut with "…". */
function clipWords(s, max) {
  return s.length > max ? `${s.slice(0, max).replace(/\s+\S*$/, '')}…` : s;
}

/** Drops the punctuation and spaces at the end ("in the kitchen." -> "in the kitchen"). */
const trimEndPunctuation = (s) => s.replace(/[.;,!?\s]+$/, '');

/** Drops what a model wraps a value in: markdown emphasis, quotes and brackets ("**'in the kitchen'**"). */
const stripWrapping = (s) => s.replace(/^[\s*_"'“”‘’()[\]]+/, '').replace(/[\s*_"'“”‘’()[\]]+$/, '');

/** "a" / "a and b" / "a, b and c". */
function joinNatural(list) {
  if (list.length <= 1) return list.join('');
  return `${list.slice(0, -1).join(', ')} and ${list[list.length - 1]}`;
}

/** What went wrong, as text, whatever was thrown (an Error, a string, anything): never "undefined". */
const errorMessage = (e) => (e instanceof Error ? e.message : String(e));
return { capitalizeFirst, cleanString, oneLine, toSentence, clipWords, trimEndPunctuation, stripWrapping, joinNatural, errorMessage };
});

__def("src/core/time.js", function () {
// Wall-clock time in the person's time zone. The run executes in Kindroid's container, whose clock zone is not the
// person's, so every wall time (a wake-up at 07:30, "23:10 on Friday") goes through an explicit IANA zone that the
// screen saved in settings.json. Plain Intl: no dependency, and the same code runs in Node and in the screen.

const LOCALE = 'en-US';
const partFormats = new Map();

/** A valid IANA zone, or 'UTC'. */
function safeTimeZone(tz) {
  if (typeof tz !== 'string' || !tz) return 'UTC';
  try { new Intl.DateTimeFormat(LOCALE, { timeZone: tz }); return tz; } catch { return 'UTC'; }
}

/** The person's zone as the browser knows it (the screen saves it for the run). */
function deviceTimeZone() {
  try { return safeTimeZone(Intl.DateTimeFormat().resolvedOptions().timeZone); } catch { return 'UTC'; }
}

/**
 * { y, m, d, h, min, s, weekday } of a moment on the wall clock of a zone (an unknown zone is UTC). The formatter is
 * kept per zone as given, so the zone is checked (a formatter made and thrown away) only the first time.
 */
function zonedParts(date, tz) {
  let f = partFormats.get(tz);
  if (!f) {
    f = new Intl.DateTimeFormat(LOCALE, { timeZone: safeTimeZone(tz), hourCycle: 'h23', year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric', second: 'numeric', weekday: 'long' });
    partFormats.set(tz, f);
  }
  const p = {};
  for (const { type, value } of f.formatToParts(date)) p[type] = value;
  return {
    y: Number(p.year), m: Number(p.month), d: Number(p.day),
    h: Number(p.hour) % 24, min: Number(p.minute), s: Number(p.second), weekday: p.weekday,
  };
}

/**
 * The moment when the wall clock of a zone shows y-m-d h:min. Around a daylight-saving change there are two offsets:
 * both are tried. A time shown twice (clocks go back) is its first moment; a time that is skipped (clocks go forward)
 * moves forward, in every zone (London, Berlin and Sydney as well as New York).
 */
function zonedTime({ y, m, d, h, min }, tz) {
  const want = Date.UTC(y, m - 1, d, h, min);
  const shown = (t) => { const p = zonedParts(new Date(t), tz); return Date.UTC(p.y, p.m - 1, p.d, p.h, p.min); };
  const offsetAt = (t) => shown(t) - t;
  const candidates = [...new Set([offsetAt(want - 864e5 / 2), offsetAt(want + 864e5 / 2), offsetAt(want)].map((o) => want - o))];
  const exact = candidates.filter((t) => shown(t) === want);
  return new Date(exact.length ? Math.min(...exact) : Math.max(...candidates));
}

/** The calendar day after { y, m, d } (month and year ends included), whatever the length of that day in a zone. */
function dayAfter({ y, m, d }) {
  const next = new Date(Date.UTC(y, m - 1, d + 1));
  return { y: next.getUTCFullYear(), m: next.getUTCMonth() + 1, d: next.getUTCDate() };
}

/** The next moment, after `now`, when the wall clock of the zone shows h:m. */
function nextWallTime({ h, m }, now, tz) {
  const today = zonedParts(now, tz);
  let at = zonedTime({ y: today.y, m: today.m, d: today.d, h, min: m }, tz);
  if (at <= now) at = zonedTime({ ...dayAfter(today), h, min: m }, tz);
  return at;
}

/** 7, 5 -> "07:05": a 24-hour clock time. */
const clockText = (h, m) => `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;

/** "23:10 on Friday" on the person's clock, for the Kin. */
function describeNow(now, tz) {
  const p = zonedParts(now, tz);
  return `${clockText(p.h, p.min)} on ${p.weekday}`;
}
return { safeTimeZone, deviceTimeZone, zonedParts, zonedTime, dayAfter, nextWallTime, clockText, describeNow };
});

__def("src/screen/announcer.js", function () {
// What a screen reader is told. Two regions that stay in the page (a region rebuilt on every render would be read
// again and again): results and notes are polite, errors are assertive.
const { h } = __req("src/screen/dom.js");

function createAnnouncer(doc) {
  const live = h('div', { class: 'sr-only', role: 'status', 'aria-live': 'polite' });
  const alertLive = h('div', { class: 'sr-only', role: 'alert' });
  doc.body.append(live, alertLive);
  // Emptied first, then filled a moment later: the same text twice in a row is still read.
  const say = (region, text) => { region.textContent = ''; setTimeout(() => { region.textContent = text; }, 30); };
  let lastAlert = '';
  return {
    announce(text) { if (text) say(live, text); },
    /** An error is told once; the same error again only after forget() (a new try). */
    alertOnce(text) {
      if (text && text !== lastAlert) say(alertLive, text);
      lastAlert = text || '';
    },
    forget() { lastAlert = ''; },
  };
}
return { createAnnouncer };
});

__def("src/screen/app.js", function () {
// The screen: a view of status.json (written by the run) and the controls that write settings.json. The run does the
// work, every 15 minutes or when Update status is pressed; the screen never asks the Kin anything itself.
// Here the pieces meet: the store (state and actions), the announcer (screen reader), the views (the page) and what
// only the page knows: focus, the ruler's drag, the theme and the timers.
const { h, keepFocus } = __req("src/screen/dom.js");
const { createStore } = __req("src/screen/store.js");
const { createAnnouncer } = __req("src/screen/announcer.js");
const { renderCard } = __req("src/screen/views/card.js");
const { renderSettings } = __req("src/screen/views/settings.js");
const { formatRelative } = __req("src/core/format.js");

const POLL_MS = 60000; // status.json is read again every minute while the screen is visible
const RELATIVE_MS = 30000; // "5 minutes ago" is brought up to date this often

function applyTheme(id) {
  if (id === 'sage') document.documentElement.setAttribute('data-theme', 'sage');
  else document.documentElement.removeAttribute('data-theme');
}

/**
 * Starts the screen on a connected channel. `kins` is the first list from the page (null when the page answered
 * files but not the Kins, e.g. a still picture of the screen: the names then come from status.json).
 */
async function startApp({ root, channel, kins, clock = () => new Date() }) {
  const announcer = createAnnouncer(document);
  const store = createStore({ channel, kins, clock, announcer, onChange: () => render() });

  // A render asked for while the ruler's thumb is held waits for the release.
  let dragging = false;
  let renderPending = false;
  const endDrag = () => { if (!dragging) return; dragging = false; if (renderPending) render(); };
  window.addEventListener('pointerup', endDrag);
  window.addEventListener('pointercancel', endDrag);

  const ui = {
    renderAndFocus(key) { render(); const el = root.querySelector(`[data-key="${key}"]`); if (el) el.focus(); },
    startDrag() { dragging = true; },
    stopDrag() { dragging = false; },
    applyTheme,
  };

  function render() {
    if (dragging) { renderPending = true; return; }
    renderPending = false;
    const now = clock();
    const v = { S: store.S, store, ui, now, at: { settings: store.S.settings, now } };
    const hadFocus = root.contains(document.activeElement);
    keepFocus(root, () => {
      root.replaceChildren(
        h('header', { class: 'app-head' }, h('h1', {}, 'Clotheskin'), h('p', {}, 'Where your Kin is, what it is doing and what it is wearing')),
        renderCard(v),
        ...(store.selectedKin() ? [renderSettings(v)] : []), // replaceChildren would show a null as the text "null"
      );
    });
    // The focused control is gone (a banner closed, Wake now done, the Kin detached): the keyboard stays in the app.
    if (hadFocus && !root.contains(document.activeElement)) {
      const fallback = root.querySelector('[data-key="update"], [data-key^="pick-"], button');
      if (fallback) fallback.focus();
    }
  }

  await store.loadSettings();
  applyTheme(store.S.settings.theme);
  await store.loadStatus();
  store.syncSettings();
  channel.onKins((list) => store.kinsChanged(list));
  setInterval(() => { if (document.visibilityState !== 'hidden') store.loadStatus(); }, POLL_MS);
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') store.loadStatus(); });
  setInterval(() => { for (const el of root.querySelectorAll('.rel[data-iso]')) el.textContent = formatRelative(el.dataset.iso, clock()); }, RELATIVE_MS);
  render();
}
return { startApp };
});

